import unittest

from solution import claim_completed


class ClaimCompletedTests(unittest.TestCase):
    def test_claims_only_newly_completed_in_order(self):
        tasks = [
            {"id": "a", "completed": True, "claimed": False, "extra": 1},
            {"id": "b", "completed": False, "claimed": False},
            {"id": "c", "completed": True, "claimed": True},
            {"id": "d", "completed": True, "claimed": False},
        ]
        updated, identifiers = claim_completed(tasks)
        self.assertEqual(identifiers, ["a", "d"])
        self.assertEqual([task["claimed"] for task in updated], [True, False, True, True])
        self.assertEqual(tasks[0]["claimed"], False)
        self.assertEqual(updated[0]["extra"], 1)

    def test_empty_and_general_non_string_iterable(self):
        self.assertEqual(claim_completed([]), ([], []))
        source = ({"id": "x", "completed": True, "claimed": False} for _ in range(1))
        self.assertEqual(claim_completed(source)[1], ["x"])

    def test_deep_copy_independence(self):
        tasks = [{
            "id": "a", "completed": True, "claimed": False,
            "details": {"values": [1]}
        }]
        updated, _ = claim_completed(tasks)
        self.assertIsNot(updated, tasks)
        self.assertIsNot(updated[0], tasks[0])
        self.assertIsNot(updated[0]["details"], tasks[0]["details"])
        updated[0]["details"]["values"].append(2)
        self.assertEqual(tasks[0]["details"], {"values": [1]})
        tasks[0]["details"]["values"].append(3)
        self.assertEqual(updated[0]["details"], {"values": [1, 2]})

    def test_invalid_outer_and_task_types(self):
        for value in ("tasks", b"tasks", 1, None):
            with self.subTest(value=value):
                with self.assertRaises(TypeError):
                    claim_completed(value)
        for value in ([1], [[("id", "x")]], [None]):
            with self.assertRaises(TypeError):
                claim_completed(value)

    def test_missing_fields_and_identifier_validation(self):
        base = {"id": "x", "completed": True, "claimed": False}
        for missing in ("id", "completed", "claimed"):
            task = dict(base)
            del task[missing]
            with self.assertRaises(ValueError):
                claim_completed([task])
        for identifier in (1, True, None):
            task = dict(base, id=identifier)
            with self.assertRaises(TypeError):
                claim_completed([task])
        with self.assertRaises(ValueError):
            claim_completed([dict(base, id="")])
        with self.assertRaises(ValueError):
            claim_completed([base, dict(base)])

    def test_statuses_must_be_actual_booleans(self):
        for field in ("completed", "claimed"):
            for value in (0, 1, None, "false"):
                task = {"id": "x", "completed": False, "claimed": False}
                task[field] = value
                with self.subTest(field=field, value=value):
                    with self.assertRaises(TypeError):
                        claim_completed([task])


if __name__ == "__main__":
    unittest.main()

